def make_variant(section, mode, fake_path=None):
    body = section["text"]
    if mode == "A0":
        return body
    if mode == "A2":
        return body
    if mode == "A3":
        return " › ".join(section["path"]) + "\n" + body
    if mode == "P":
        assert fake_path is not None
        return " › ".join(fake_path) + "\n" + body
    raise ValueError(mode)

